ValidationRule.errorConditionFormula:
IF( $UserRole.Name="System Administrator", FALSE, AND( OR(ISCHANGED(Status__c), ISCHANGED(Approval_Status__c)),
/* 範圍：核准∈{New, In Progress, Approved}(前/後)，且排除 Reapplied 與 CA/DR/Rejected 與 S2 的 New 分支 */ AND( OR( ISPICKVAL(Approval_Status__c, "New"), ISPICKVAL(Approval_Status__c, "In Progress"), ISPICKVAL(Approval_Status__c, "Approved"), ISPICKVAL(PRIORVALUE(Approval_Status__c), "New"), ISPICKVAL(PRIORVALUE(Approval_Status__c), "In Progress"), ISPICKVAL(PRIORVALUE(Approval_Status__c), "Approved") ), NOT( OR( /* 排除任何 Reapplied（前/後） */ TEXT(Status__c) = "Reapplied", TEXT(PRIORVALUE(Status__c)) = "Reapplied",
/* 排除 CA / DR / Rejected（前/後） */ ISPICKVAL(Approval_Status__c, "Conditionally Approved"), ISPICKVAL(Approval_Status__c, "Documents Required"), ISPICKVAL(Approval_Status__c, "Rejected"), ISPICKVAL(PRIORVALUE(Approval_Status__c), "Conditionally Approved"), ISPICKVAL(PRIORVALUE(Approval_Status__c), "Documents Required"), ISPICKVAL(PRIORVALUE(Approval_Status__c), "Rejected"),
/* ⬅ 新增：排除 S2 的 New 分支（前/後）*/ AND(TEXT(Status__c)="Replied", TEXT(Approval_Status__c)="New"), AND(TEXT(Status__c)="Closed", TEXT(Approval_Status__c)="New"), AND(TEXT(PRIORVALUE(Status__c))="Replied", TEXT(PRIORVALUE(Approval_Status__c))="New"), AND(TEXT(PRIORVALUE(Status__c))="Closed", TEXT(PRIORVALUE(Approval_Status__c))="New") ) ) ),
/* 白名單：0→5（不是未變更且不在清單就擋） */ NOT( OR( AND( TEXT(PRIORVALUE(Status__c)) = TEXT(Status__c), TEXT(PRIORVALUE(Approval_Status__c)) = TEXT(Approval_Status__c) ), CONTAINS( ";" & "New|New>In Progress|New;" & "In Progress|New>In Progress|In Progress;" & "In Progress|In Progress>In Progress|Approved;" & "In Progress|Approved>Replied|Approved;" & "Replied|Approved>Closed|Approved;" & ";", ";" & TEXT(PRIORVALUE(Status__c)) & "|" & TEXT(PRIORVALUE(Approval_Status__c)) & ">" & TEXT(Status__c) & "|" & TEXT(Approval_Status__c) & ";" ) ) ) ) )
